insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ReplyRight', 'reply-right', 'Answer customer emails in seconds, not hours', 'ReplyRight reads incoming customer emails and drafts on-brand responses instantly. Your team reviews and sends - cutting reply time by 80%. It learns your voice, knows your FAQs, and handles everything from billing questions to complaints with empathy and professionalism.', 'https://example.com/replyright', 'https://api.dicebear.com/7.x/shapes/svg?seed=replyright&backgroundColor=bfdbfe', 'Writing & Communication', ARRAY['E-commerce', 'SaaS', 'Customer Service'], ARRAY['Gmail', 'Outlook', 'Zendesk', 'Intercom', 'Freshdesk'], 'subscription', 'plug_and_play', true, 4.6, 318);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('BriefBot', 'brief-bot', 'Turn long reports into one-page executive summaries', 'BriefBot condenses lengthy documents, research reports, and email threads into crisp, decision-ready summaries. Upload a PDF or paste a link and get a structured brief in under 30 seconds. Used by executives, chiefs of staff, and consultants who need to stay informed without reading everything.', 'https://example.com/briefbot', 'https://api.dicebear.com/7.x/shapes/svg?seed=briefbot&backgroundColor=e0e7ff', 'Writing & Communication', ARRAY['Consulting', 'Finance', 'Executive', 'Legal'], ARRAY['Notion', 'Google Drive', 'Dropbox', 'Slack', 'Outlook'], 'freemium', 'plug_and_play', true, 4.4, 193);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('AgendaAI', 'agenda-ai', 'Build a structured meeting agenda in 60 seconds', 'AgendaAI creates clear, timed agendas from a quick description of your meeting goals. It suggests the right format based on meeting type - standup, brainstorm, decision meeting, or retrospective - and shares a clean agenda with attendees before the call.', 'https://example.com/agendaai', 'https://api.dicebear.com/7.x/shapes/svg?seed=agendaai&backgroundColor=d1fae5', 'Productivity & Meetings', ARRAY['Operations', 'Product', 'Executive', 'Consulting'], ARRAY['Google Calendar', 'Outlook Calendar', 'Slack', 'Notion', 'Microsoft Teams'], 'freemium', 'plug_and_play', true, 4.3, 142);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('FollowUp', 'followup', 'Never let a follow-up fall through the cracks again', 'FollowUp monitors your email and calendar, identifies commitments you made in meetings and emails, and sends you gentle reminders before things go stale. It tracks promises you make so you always follow through.', 'https://example.com/followup', 'https://api.dicebear.com/7.x/shapes/svg?seed=followup&backgroundColor=fef3c7', 'Productivity & Meetings', ARRAY['Sales', 'Consulting', 'Executive', 'HR'], ARRAY['Gmail', 'Outlook', 'Google Calendar', 'Slack'], 'subscription', 'plug_and_play', false, 4.0, 67);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('RecapAI', 'recap-ai', 'Your weekly work summary, written automatically', 'RecapAI pulls from your calendar, emails, and project tools to write a professional weekly update every Friday. Share it with your manager, your team, or keep it for your own records. No more staring at a blank page trying to remember what you accomplished.', 'https://example.com/recapai', 'https://api.dicebear.com/7.x/shapes/svg?seed=recapai&backgroundColor=cffafe', 'Productivity & Meetings', ARRAY['Operations', 'Marketing', 'Engineering', 'Finance'], ARRAY['Google Calendar', 'Jira', 'Notion', 'Slack', 'Asana', 'Gmail'], 'freemium', 'low', true, 4.5, 228);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('TrendSpotter', 'trend-spotter', 'Know what is changing in your business before it becomes a problem', 'TrendSpotter connects to your sales, support, and ops data and sends a plain-English weekly digest highlighting unusual patterns - a dip in conversion, a spike in refunds, a region that is outperforming. No dashboard required. It comes to you.', 'https://example.com/trendspotter', 'https://api.dicebear.com/7.x/shapes/svg?seed=trendspotter&backgroundColor=fde68a', 'Data & Analytics', ARRAY['Retail', 'E-commerce', 'SaaS', 'Finance'], ARRAY['Shopify', 'Salesforce', 'HubSpot', 'Google Analytics', 'Stripe'], 'subscription', 'low', true, 4.4, 175);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ReportGenie', 'report-genie', 'Generate board-ready reports from your existing data', 'ReportGenie connects to your data sources and automatically produces polished reports with charts, tables, and narrative summaries. Set it on a schedule and it delivers a PDF to your inbox - ready to share with executives, investors, or clients without any manual formatting.', 'https://example.com/reportgenie', 'https://api.dicebear.com/7.x/shapes/svg?seed=reportgenie&backgroundColor=fca5a5', 'Data & Analytics', ARRAY['Finance', 'Operations', 'Marketing', 'Healthcare'], ARRAY['Google Sheets', 'Excel', 'Salesforce', 'HubSpot', 'QuickBooks'], 'subscription', 'medium', true, 4.2, 134);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('OnboardIQ', 'onboard-iq', 'Give every new hire a smooth first week - automatically', 'OnboardIQ creates personalized onboarding plans for new employees based on their role, team, and start date. It sends welcome emails, schedules intro meetings, assigns training tasks, and checks in at day 3, week 1, and month 1 - all without HR lifting a finger.', 'https://example.com/onboardiq', 'https://api.dicebear.com/7.x/shapes/svg?seed=onboardiq&backgroundColor=bbf7d0', 'HR & Recruiting', ARRAY['HR', 'Tech', 'Finance', 'Healthcare', 'Retail'], ARRAY['Workday', 'BambooHR', 'Slack', 'Gmail', 'Google Calendar', 'Notion'], 'subscription', 'medium', true, 4.6, 209);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('PulseCheck', 'pulse-check', 'Spot disengaged employees before they quit', 'PulseCheck runs lightweight, anonymous weekly check-ins with your team and surfaces insights about morale, blockers, and burnout risk. Managers get a simple dashboard showing team health trends over time - no lengthy annual surveys required.', 'https://example.com/pulsecheck', 'https://api.dicebear.com/7.x/shapes/svg?seed=pulsecheck&backgroundColor=ddd6fe', 'HR & Recruiting', ARRAY['HR', 'Operations', 'Tech', 'Finance'], ARRAY['Slack', 'Microsoft Teams', 'BambooHR', 'Workday'], 'subscription', 'plug_and_play', true, 4.5, 167);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('RenewalRadar', 'renewal-radar', 'Never miss a renewal conversation again', 'RenewalRadar tracks every customer contract and automatically triggers outreach sequences 90, 60, and 30 days before renewal. It personalizes each message based on the account usage and health score, so your team shows up to renewals prepared - not scrambling.', 'https://example.com/renewalradar', 'https://api.dicebear.com/7.x/shapes/svg?seed=renewalradar&backgroundColor=fed7aa', 'Customer Success', ARRAY['SaaS', 'Professional Services', 'Insurance'], ARRAY['Salesforce', 'HubSpot', 'Gainsight', 'Gmail', 'Slack'], 'subscription', 'low', true, 4.7, 143);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('WinbackAI', 'winback-ai', 'Re-engage churned customers with the right message at the right time', 'WinbackAI analyzes why customers left, segments them by churn reason, and runs personalized re-engagement campaigns. It knows which customers are worth pursuing and what offer is likely to bring them back - saving your team from blanket discount blasts that erode margin.', 'https://example.com/winbackai', 'https://api.dicebear.com/7.x/shapes/svg?seed=winbackai&backgroundColor=fda4af', 'Customer Success', ARRAY['SaaS', 'E-commerce', 'Media', 'Finance'], ARRAY['HubSpot', 'Salesforce', 'Klaviyo', 'Gmail', 'Stripe'], 'usage_based', 'low', false, 3.9, 54);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ProspectPilot', 'prospect-pilot', 'Find your next 50 ideal customers while you sleep', 'ProspectPilot builds targeted prospect lists based on your ideal customer profile, enriches each contact with verified emails and LinkedIn profiles, and drafts personalized first-touch messages. Sales reps wake up to a ready-to-send outreach queue every morning.', 'https://example.com/prospectpilot', 'https://api.dicebear.com/7.x/shapes/svg?seed=prospectpilot&backgroundColor=bae6fd', 'Sales', ARRAY['SaaS', 'Professional Services', 'Finance', 'Tech'], ARRAY['Salesforce', 'HubSpot', 'LinkedIn', 'Gmail', 'Outreach', 'Apollo'], 'subscription', 'low', true, 4.5, 287);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('DealCoach', 'deal-coach', 'Get an honest read on every deal in your pipeline', 'DealCoach analyzes your CRM notes, email activity, and call transcripts to give each opportunity a health score and a clear next-best-action. It flags deals going cold before they are lost and surfaces the objections most likely to kill the close.', 'https://example.com/dealcoach', 'https://api.dicebear.com/7.x/shapes/svg?seed=dealcoach&backgroundColor=a7f3d0', 'Sales', ARRAY['SaaS', 'Finance', 'Real Estate', 'Professional Services'], ARRAY['Salesforce', 'HubSpot', 'Gong', 'Chorus', 'Gmail'], 'subscription', 'medium', true, 4.4, 198);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ExpenseEye', 'expense-eye', 'Catch wasteful spending before it hits the budget', 'ExpenseEye connects to your company credit cards and accounting software, categorizes every transaction automatically, and alerts you when spending trends are off. Finance teams use it to close the books faster and catch duplicate subscriptions, overspending, and policy violations.', 'https://example.com/expenseeye', 'https://api.dicebear.com/7.x/shapes/svg?seed=expenseeye&backgroundColor=fef08a', 'Finance', ARRAY['Finance', 'Operations', 'HR', 'Retail'], ARRAY['QuickBooks', 'Xero', 'NetSuite', 'Expensify', 'Ramp', 'Brex'], 'subscription', 'low', true, 4.3, 221);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ForecastAI', 'forecast-ai', 'Revenue forecasts you can actually trust', 'ForecastAI combines your historical sales data, pipeline, and seasonal patterns to produce rolling revenue forecasts that update automatically. Finance and sales leaders get a shared view of the number - no more spreadsheet wars or end-of-quarter surprises.', 'https://example.com/forecastai', 'https://api.dicebear.com/7.x/shapes/svg?seed=forecastai&backgroundColor=fbcfe8', 'Finance', ARRAY['SaaS', 'Finance', 'Retail', 'Manufacturing'], ARRAY['Salesforce', 'HubSpot', 'QuickBooks', 'NetSuite', 'Excel'], 'subscription', 'medium', false, 4.1, 89);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ContractCheck', 'contract-check', 'Know what you are signing before you sign it', 'ContractCheck reviews contracts and highlights key clauses, unusual terms, and potential risks in plain English. It flags auto-renewal traps, liability limits, IP ownership issues, and termination conditions - so you walk into every negotiation informed, even without a lawyer on call.', 'https://example.com/contractcheck', 'https://api.dicebear.com/7.x/shapes/svg?seed=contractcheck&backgroundColor=c7d2fe', 'Legal', ARRAY['Legal', 'Finance', 'Operations', 'Executive', 'Real Estate'], ARRAY['DocuSign', 'Google Drive', 'Dropbox', 'Microsoft Word', 'Notion'], 'freemium', 'plug_and_play', true, 4.6, 334);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ContentCalAI', 'content-cal-ai', 'A month of social content, planned and drafted in an afternoon', 'ContentCalAI generates a full monthly content calendar tailored to your brand, industry, and goals. It drafts captions, suggests visuals, and schedules posts across your channels. Marketing teams use it to stay consistent without scrambling for ideas every week.', 'https://example.com/contentcalai', 'https://api.dicebear.com/7.x/shapes/svg?seed=contentcalai&backgroundColor=d9f99d', 'Marketing', ARRAY['Marketing', 'E-commerce', 'SaaS', 'Retail', 'Media'], ARRAY['LinkedIn', 'Instagram', 'Twitter', 'Buffer', 'Hootsuite', 'Notion'], 'subscription', 'plug_and_play', true, 4.4, 412);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('AdOptimizer', 'ad-optimizer', 'Stop wasting ad budget on what is not working', 'AdOptimizer monitors your paid campaigns across Google and Meta, identifies underperforming ads, and suggests copy and targeting tweaks backed by your own performance data. Marketing managers get a weekly action plan - no agency or data analyst required.', 'https://example.com/adoptimizer', 'https://api.dicebear.com/7.x/shapes/svg?seed=adoptimizer&backgroundColor=fcd34d', 'Marketing', ARRAY['E-commerce', 'SaaS', 'Retail', 'Marketing'], ARRAY['Google Ads', 'Meta Ads', 'Shopify', 'HubSpot', 'Google Analytics'], 'subscription', 'low', true, 4.3, 176);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('AccessAudit', 'access-audit', 'Know exactly who has access to what - and flag what should not be there', 'AccessAudit scans your SaaS tools and surfaces employees with excessive permissions, dormant accounts that should be deactivated, and apps your team is using that IT does not know about. It produces a clean access report that takes minutes to review, not days to compile.', 'https://example.com/accessaudit', 'https://api.dicebear.com/7.x/shapes/svg?seed=accessaudit&backgroundColor=e2e8f0', 'IT & Security', ARRAY['IT', 'Security', 'Finance', 'Healthcare', 'Legal'], ARRAY['Okta', 'Google Workspace', 'Microsoft 365', 'Slack', 'GitHub', 'Salesforce'], 'subscription', 'medium', true, 4.5, 118);
